package workerhost

import (
	"bytes"
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/unreallabsai/unreal-agent/cmd/internal/workerproto"
	"github.com/unreallabsai/unreal-agent/harness/llm"
	"github.com/unreallabsai/unreal-agent/harness/sessionstore/localfile"
)

// Fixture bytes are preserved from LOCAL a5f3fd13032737142916523ae4344c392292f9d5
// harness/sessionstore/localfile/testdata; never regenerated by this test. The v2
// store is backward readable, but its unfinished unknown "test" op is not runtime
// replay permission. Legacy v1 remains deliberately unsupported, not migrated.
func TestM34HistoricalStoreReadsAndStartupRefusalPreserveSource(t *testing.T) {
	supported, err := os.ReadFile("testdata/m34/upstream-a5f3-golden-v2.session.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	legacy, err := os.ReadFile("testdata/m34/upstream-a5f3-legacy-v1.session.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	t.Run("supported-v2-read", func(t *testing.T) {
		dir := t.TempDir()
		if err := os.Chmod(dir, 0700); err != nil {
			t.Fatal(err)
		}
		path := filepath.Join(dir, "golden-session.session.jsonl")
		if err := os.WriteFile(path, supported, 0600); err != nil {
			t.Fatal(err)
		}
		store, err := localfile.New(dir)
		if err != nil {
			t.Fatal(err)
		}
		snapshot, err := store.Resume(t.Context(), "golden-session")
		if err != nil {
			t.Fatal(err)
		}
		if snapshot.Snapshot.Session.ID != "golden-session" || len(snapshot.Operations) != 1 || snapshot.Operations[0].ID != "operation-1" || snapshot.Operations[0].Status != "awaiting" || !bytes.Contains(snapshot.Operations[0].State, []byte(`"step":2`)) {
			t.Fatalf("historical meaning changed: %+v", snapshot)
		}
		after, err := os.ReadFile(path)
		if err != nil || !bytes.Equal(after, supported) {
			t.Fatal("read rewrote historical fixture", err)
		}
	})
	// These are real worker startups, not merely pure decoder calls. No provider
	// request or canonical write may happen before an unsupported fence refuses.
	for _, tc := range []struct {
		name string
		data []byte
		want string
	}{
		{"legacy-v1", legacy, "legacy session format version 1 cannot be resumed"},
		{"future-header", bytes.Replace(supported, []byte(`"Version":2`), []byte(`"Version":999`), 1), "unsupported session format version"},
		{"historical-unknown-checkpoint", supported, "recovery refused"},
		{"future-checkpoint", bytes.ReplaceAll(bytes.ReplaceAll(supported, []byte(`"Type":"test"`), []byte(`"Type":"shell"`)), []byte(`"Version":1`), []byte(`"Version":999`)), "recovery refused"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv("UA_HOST_TEST_REAL", "1")
			t.Setenv("OPENAI_API_KEY", "fake-loopback-only")
			t.Setenv("UNREAL_HARNESS_LLM_API_KEY", "fake-loopback-only")
			dir := t.TempDir()
			_ = os.Chmod(dir, 0700)
			t.Setenv("HOME", dir)
			t.Setenv("XDG_CONFIG_HOME", filepath.Join(dir, "config"))
			path := filepath.Join(dir, "golden-session.session.jsonl")
			if err := os.WriteFile(path, tc.data, 0600); err != nil {
				t.Fatal(err)
			}
			var calls atomic.Int64
			provider := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				calls.Add(1)
				http.Error(w, "refused state must not reach provider", 500)
			}))
			defer provider.Close()
			exe, err := os.Executable()
			if err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
			defer cancel()
			h, err := Start(ctx, Config{Command: []string{exe, "-test.run=^$", "worker"}, Bootstrap: workerproto.Bootstrap{SessionID: "golden-session", Directory: dir, Workspace: dir, Provider: "openai", BaseURL: provider.URL, MaxAttempts: 1, Model: llm.Model{ID: "fake", CompactionThreshold: 64000}, Shell: "/bin/sh"}, Stderr: os.Stderr})
			if h != nil {
				closeCtx, stop := context.WithTimeout(context.Background(), 5*time.Second)
				_ = h.Close(closeCtx)
				stop()
			}
			if err == nil || !strings.Contains(err.Error(), tc.want) || calls.Load() != 0 {
				t.Fatalf("fence did not refuse before provider: err=%v calls=%d", err, calls.Load())
			}
			after, e := os.ReadFile(path)
			if e != nil || !bytes.Equal(after, tc.data) {
				t.Fatal("unsupported startup mutated canonical source", e)
			}
		})
	}
}
